# What "for x in obj" really does
def manual_for(obj):
    it = iter(obj)                    # GET_ITER: called once
    while True:
        try:
            x = next(it)              # FOR_ITER: one next() per pass
        except StopIteration:
            print("else clause runs")  # loop ended without break
            return
        print("got", x)

manual_for("ab")

