from collections import Counter
# Generator pipeline: one line in flight at a time
def source():                         # stands in for: for line in open(...)
    lines = ["2024 ERROR auth boom", "2024 INFO web ok", "garbage",
             "2024 ERROR web 500", "2024 ERROR auth timeout"]
    for line in lines:
        yield line

def parse(lines):
    for line in lines:
        parts = line.split(" ", 3)    # max split keeps it cheap
        if len(parts) < 4:
            continue                  # skip malformed lines
        yield parts[1], parts[2]

def errors(rows):
    for level, svc in rows:
        if level == "ERROR":
            yield svc

counts = Counter(errors(parse(source())))   # sink pulls the stream
print(dict(counts))                   # memory: O(distinct services)
# Time O(lines), space O(services)

from contextlib import contextmanager
# A generator becomes a context manager
@contextmanager
def tag(name):
    print("<%s>" % name)              # setup: runs in __enter__
    try:
        yield name.upper()            # value bound by 'as'
    finally:
        print("</%s>" % name)         # cleanup, even on error

with tag("b") as t:
    print("inside", t)
try:
    with tag("i"):
        raise RuntimeError("fail")    # thrown into the generator at yield
except RuntimeError:
    print("error propagated")

@contextmanager
def swallow():
    try:
        yield
    except ZeroDivisionError:
        print("swallowed")            # not re-raised: suppressed
with swallow():
    1 / 0
cm = tag("u")
with cm:
    pass
try:
    with cm:                          # generator is already finished
        pass
except (RuntimeError, AttributeError):
    print("reuse fails")

from contextlib import ExitStack
# ExitStack: a run-time number of resources
class Res:
    def __init__(self, name, fail=False):
        self.name, self.fail = name, fail
    def __enter__(self):
        if self.fail:
            raise OSError("cannot open " + self.name)
        print("open", self.name)
        return self
    def __exit__(self, *exc):
        print("close", self.name)

with ExitStack() as stack:
    for n in ["a", "b", "c"]:
        stack.enter_context(Res(n))
    stack.callback(print, "custom callback")
    print("working")                  # exit order is LIFO

def open_all(names):
    with ExitStack() as stack:
        rs = [stack.enter_context(Res(n, fail=(n == "z"))) for n in names]
        keep = stack.pop_all()        # success: hand ownership to caller
        return rs, keep
try:
    open_all(["x", "y", "z"])         # z fails: x and y are closed
except OSError as e:
    print("failed:", e)
rs, keep = open_all(["p", "q"])
print("caller owns", len(rs))
keep.close()

from contextlib import closing
# Early break: when does the resource close?
class FakeFile:
    def __enter__(self):
        print("  file opened")
        return self
    def __exit__(self, *a):
        print("  file closed")
    def __iter__(self):
        return iter(["l1", "l2", "l3"])

def lines():
    with FakeFile() as f:
        for line in f:
            yield line                # suspended inside the with

print("explicit close:")
g = lines()
for x in g:
    print(" got", x)
    break
print(" still open here")
g.close()                             # GeneratorExit runs __exit__

print("closing() helper:")
with closing(lines()) as g2:
    for x in g2:
        break                         # closed when the block ends
print("refcount GC (CPython):")
g3 = lines()
next(g3)
del g3                                # last reference gone: closes now
print("done")

# zip written by hand
def my_zip(*args):
    its = [iter(a) for a in args]
    if not its:
        return                        # zero args: yield nothing
    while True:
        row = []
        for it in its:                # list loop, not a genexp (PEP 479)
            try:
                row.append(next(it))
            except StopIteration:
                return                # shortest input ends the zip
        yield tuple(row)

print(list(my_zip([1, 2, 3], "ab")))
print(list(my_zip()))
a = iter([1, 2, 3])
b = iter("x")
print(list(my_zip(a, b)), "-> a still has:", list(a))   # 2 was pulled, lost
print(list(zip([1, 2, 3], "ab")))     # same as the built-in
